import { createClient } from '@supabase/supabase-js'

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL
const supabaseKey = import.meta.env.VITE_SUPABASE_ANON_KEY

if (!supabaseUrl || !supabaseKey) {
  throw new Error('Missing Supabase environment variables')
}

export const supabase = createClient(supabaseUrl, supabaseKey)

export interface Page {
  id: number
  title: string
  slug: string
  content: string
  meta_description?: string
  is_published: boolean
  created_at: string
  updated_at: string
}

export interface Contact {
  id: number
  name: string
  email: string
  message: string
  created_at: string
}

export interface HeroSlide {
  id: number
  title: string
  subtitle: string
  description: string
  image_url: string
  cta_text: string
  cta_link: string
  order_index: number
  is_active: boolean
}

export interface Benefit {
  id: number
  title: string
  description: string
  icon: string
  order_index: number
  is_active: boolean
}

export interface Testimonial {
  id: number
  name: string
  company: string
  position: string
  content: string
  avatar_url?: string
  rating: number
  order_index: number
  is_active: boolean
}

export interface ProcessStep {
  id: number
  title: string
  description: string
  icon: string
  order_index: number
  is_active: boolean
}

export interface ChatMessage {
  id: number
  message: string
  response: string
  created_at: string
}
