import React from 'react';
import { useGoogleCalendar } from '../hooks/useGoogleCalendar';

const CalendarTest: React.FC = () => {
  const { isConnected, isLoading, error, checkConnectionStatus } = useGoogleCalendar();

  return (
    <div style={{ padding: '20px', fontFamily: 'Arial' }}>
      <h1>Calendar API Test</h1>
      <div>
        <p><strong>Connected:</strong> {isConnected ? '✅ Yes' : '❌ No'}</p>
        <p><strong>Loading:</strong> {isLoading ? '🔄 Yes' : '⏹️ No'}</p>
        <p><strong>Error:</strong> {error || 'None'}</p>
      </div>
      <button onClick={checkConnectionStatus}>
        🔄 Test Connection
      </button>
      <div style={{ marginTop: '20px', fontSize: '12px', color: '#666' }}>
        Check browser console for detailed logs
      </div>
    </div>
  );
};

export default CalendarTest;
